.eldsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #28323c;
    background: linear-gradient(180deg, #f6f3ec 0%, #eef1ef 100%);
    border-radius: 18px;
}

.eldsim-container * {
    box-sizing: border-box;
}

.eldsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0e3a3a 0%, #12504c 60%, #1c6b5e 100%);
    color: #f3fbf7;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 14px 32px rgba(14, 58, 58, 0.28);
}

.eldsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.eldsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f5c66b;
    background: rgba(245, 198, 107, 0.14);
    border: 1px solid rgba(245, 198, 107, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.eldsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d7e8e1;
}

.eldsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4d5d63;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.eldsim-period-counter #currentDay,
.eldsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #12504c;
}

.eldsim-round-name {
    background: rgba(18, 80, 76, 0.10);
    color: #12504c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.eldsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b4561d;
    background: rgba(214, 122, 51, 0.12);
    border: 1px solid rgba(214, 122, 51, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.eldsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.eldsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e2ded3;
    box-shadow: 0 6px 16px rgba(40, 50, 60, 0.07);
    border-top: 4px solid #1c6b5e;
}

.eldsim-card-align { border-top-color: #1c6b5e; }
.eldsim-card-reach { border-top-color: #2f7fb0; }
.eldsim-card-cost { border-top-color: #d67a33; }
.eldsim-card-impact { border-top-color: #7a5cc0; }

.eldsim-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7a80;
}

.eldsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f2a30;
    font-variant-numeric: tabular-nums;
}

.eldsim-card-align .eldsim-value { color: #1c6b5e; }
.eldsim-card-reach .eldsim-value { color: #2f7fb0; }
.eldsim-card-cost .eldsim-value { color: #c2691f; }
.eldsim-card-impact .eldsim-value { color: #7a5cc0; }

.eldsim-sublabel {
    font-size: 0.76rem;
    color: #7f8c92;
    line-height: 1.35;
}

.eldsim-align-good { border-top-color: #1c6b5e; }
.eldsim-align-good .eldsim-value { color: #178a63; }
.eldsim-align-weak .eldsim-value { color: #c0392b; }
.eldsim-cost-good .eldsim-value { color: #178a63; }
.eldsim-cost-high .eldsim-value { color: #c0392b; }
.eldsim-impact-good .eldsim-value { color: #178a63; }

.eldsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0e3a3a;
    border: 1px solid #0b2e2e;
    color: #d7e8e1;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.eldsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f5c66b;
}

.eldsim-budget-bar.eldsim-budget-over #budgetDisplay {
    color: #ff8a6b;
}

.eldsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1c6b5e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(40, 50, 60, 0.07);
}

.eldsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.eldsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #12504c;
    margin-bottom: 6px;
}

.eldsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3b474e;
}

.eldsim-briefing-text strong { color: #1c6b5e; }
.eldsim-briefing-text em { color: #b4561d; font-style: italic; }

.eldsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2ded3;
    box-shadow: 0 6px 16px rgba(40, 50, 60, 0.07);
}

.eldsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #12504c;
    border-bottom: 2px solid #ece8df;
    padding-bottom: 8px;
}

.eldsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2f3b42;
    margin: 14px 0 6px;
}

.eldsim-container select,
.eldsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cfd6d3;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #28323c;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.eldsim-container select:focus,
.eldsim-container input[type="number"]:focus {
    outline: none;
    border-color: #1c6b5e;
    box-shadow: 0 0 0 3px rgba(28, 107, 94, 0.16);
}

.eldsim-container select option {
    background-color: #ffffff;
    color: #28323c;
}

.eldsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1c6b5e;
}

.eldsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4d5d63;
    margin-top: 4px;
}

.eldsim-range-readout span:nth-child(2),
.eldsim-range-readout #classroomReadout {
    color: #1c6b5e;
    font-weight: 800;
}

.eldsim-hint {
    font-size: 0.8rem;
    color: #7f8c92;
    margin-top: 4px;
    line-height: 1.4;
}

.eldsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.eldsim-container .btn-primary {
    background: linear-gradient(135deg, #12504c 0%, #1c6b5e 100%);
    border: none;
    color: #f3fbf7;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(18, 80, 76, 0.30);
}

.eldsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.eldsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cfd6d3;
    color: #6c7a80;
    background: transparent;
}

.eldsim-coach {
    background: linear-gradient(160deg, #103a3a 0%, #16443f 100%);
    color: #e6f1ec;
    border: 1px solid #0b2e2e;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(14, 58, 58, 0.18);
}

.eldsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f5c66b;
    margin-bottom: 8px;
}

.eldsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.eldsim-coach-body strong { color: #f5c66b; }
.eldsim-coach-body em { color: #ffd9a0; font-style: italic; }

.eldsim-history,
.eldsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e2ded3;
    box-shadow: 0 6px 16px rgba(40, 50, 60, 0.07);
}

.eldsim-history h3,
.eldsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #12504c;
}

.eldsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3b474e;
}

.eldsim-container table#usfHistoryTable th {
    background: #f1efe7;
    color: #12504c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2ded3;
}

.eldsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece8df;
    color: #3b474e;
}

.eldsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f2;
}

.eldsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .eldsim-container {
        padding: 14px;
    }
    .eldsim-header h1 {
        font-size: 1.7rem;
    }
    .eldsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .eldsim-value {
        font-size: 2rem;
    }
    .eldsim-clock {
        margin-left: 0;
    }
    .eldsim-period-counter {
        font-size: 0.88rem;
    }
    .eldsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .eldsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* === eldsim-cm: completion debrief (appended, adapter 1.1.0) === */
.eldsim-cm { max-width: 640px; margin: 0 auto; font-family: inherit; }
.eldsim-cm-head { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; margin-bottom: 14px; }
.eldsim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #0b3d5c; }
.eldsim-cm-max { font-size: 1.1rem; font-weight: 600; color: #6b7a86; margin-left: 2px; }
.eldsim-cm-grade { font-size: 1.25rem; font-weight: 700; color: #123; }
.eldsim-cm-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.eldsim-cm-badge { font-size: .82rem; font-weight: 600; padding: 4px 10px; border-radius: 999px; border: 1px solid transparent; }
.eldsim-cm-ok { background: #e4f5ea; color: #1c7a43; border-color: #b7e2c7; }
.eldsim-cm-no { background: #fdecec; color: #b23b3b; border-color: #f3c4c4; }
.eldsim-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 10px; margin-bottom: 16px; }
.eldsim-cm-kpi { background: #f4f7f9; border: 1px solid #e1e8ed; border-radius: 8px; padding: 10px 8px; text-align: center; }
.eldsim-cm-kpi-v { font-size: 1.2rem; font-weight: 700; color: #0b3d5c; }
.eldsim-cm-kpi-l { font-size: .74rem; color: #6b7a86; margin-top: 3px; }
.eldsim-cm-insights { margin: 0; padding-left: 20px; }
.eldsim-cm-insights li { margin: 5px 0; line-height: 1.4; }

