(function() {
    'use strict';

    class ElevatingLDAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Elevating L&D`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Helventer Industrial Group N.V.).
            this.BUDGET = 14.6;          // EUR 14.6M frozen L&D budget
            this.UNALIGNED = 9.6;        // EUR 9.6M unaligned spend (reallocation target)
            this.ALIGN_BASE = 34;        // 34% baseline strategy-alignment score
            this.REACH_BASE = 380;       // <400/yr baseline reach in priority capabilities
            this.REACH_TARGET = 2800;    // ~2,800 reskilling gap over 24 months
            this.COST_BASE = 1180;       // EUR 1,180 classroom cost per learner (blended start)
            this.COST_CLASSROOM = 1180;  // EUR 1,180 classroom
            this.COST_DIGITAL = 190;     // EUR 190 blended/digital
            this.IMPACT_BASE = 5;        // business-impact readiness baseline (0 of 312 measured)

            // Concept truths.
            this.TRUE_DIAG = `rigorous`;
            this.TRUE_MISALIGN = `legacy`;
            this.TRUE_PROTECT = `protect`;
            this.TRUE_METRIC = `business`;
            this.TRUE_PITCH = `tradeoff`;
            this.TRUE_GOV = `quarterly`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    align: this.ALIGN_BASE,      // strategy-alignment score (%)
                    reach: this.REACH_BASE,      // priority-capability learners/yr
                    cost: this.COST_BASE,        // blended cost per learner (€)
                    impact: this.IMPACT_BASE,    // business-impact readiness (0–100)
                    budgetUsed: this.BUDGET,     // €M committed within the freeze
                    askedForMore: false,         // proposed a budget increase
                    relationalGutted: false,     // digitized relational skills
                    activityOnly: false,         // measured completions/satisfaction only
                    noGovernance: false,         // no realignment cadence
                    alignHistory: [this.ALIGN_BASE],
                    reachHistory: [this.REACH_BASE],
                    costHistory: [this.COST_BASE],
                    impactHistory: [this.IMPACT_BASE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Deliberately middling / wrong-leaning seeds — a blind click-through must not auto-win.
                state.decisions = {
                    diag: `generous`,
                    misalign: `cost`,
                    rigor: 45,
                    reallocate: 3,
                    mix: 50,
                    protect: `some`,
                    metric: `learning`,
                    chain: `vague`,
                    invest: 0.2,
                    pitch: `vision`,
                    governance: `annual`,
                    concede: `defend`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagInput`);
                const ms = document.getElementById(`misalignInput`);
                const rg = document.getElementById(`rigorInput`);
                if (dg) decisions.diag = dg.value;
                if (ms) decisions.misalign = ms.value;
                if (rg) decisions.rigor = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const re = document.getElementById(`reallocateInput`);
                const mx = document.getElementById(`mixInput`);
                const pr = document.getElementById(`protectInput`);
                if (re) decisions.reallocate = parseFloat(re.value);
                if (mx) decisions.mix = parseInt(mx.value, 10);
                if (pr) decisions.protect = pr.value;
                if (!Number.isFinite(decisions.reallocate) || decisions.reallocate < 0 || decisions.reallocate > this.UNALIGNED) {
                    warn(`warn_reallocate_range`); return false;
                }
                if (!Number.isFinite(decisions.mix) || decisions.mix < 0 || decisions.mix > 100) {
                    warn(`warn_mix_range`); return false;
                }
            } else if (round === 3) {
                const mt = document.getElementById(`metricInput`);
                const ch = document.getElementById(`chainInput`);
                const iv = document.getElementById(`investInput`);
                if (mt) decisions.metric = mt.value;
                if (ch) decisions.chain = ch.value;
                if (iv) decisions.invest = parseFloat(iv.value);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0 || decisions.invest > 1.5) {
                    warn(`warn_invest_range`); return false;
                }
            } else if (round === 4) {
                const pt = document.getElementById(`pitchInput`);
                const gv = document.getElementById(`governanceInput`);
                const cc = document.getElementById(`concedeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pt) decisions.pitch = pt.value;
                if (gv) decisions.governance = gv.value;
                if (cc) decisions.concede = cc.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let alignDelta = 0, reachDelta = 0, costDelta = 0, impactDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the portfolio honestly (Common Error 1: defending popularity; Error 4: activity as proof).
                switch (d.diag) {
                    case `rigorous`: alignDelta += 2; impactDelta += 8; coachKey = `coach_r1_rigorous`; break;
                    case `generous`: alignDelta += 6; impactDelta -= 4; coachKey = `coach_r1_generous`; break;   // inflates baseline, hides the real gap
                    case `completion`: impactDelta -= 6; coachKey = `coach_r1_completion`; break;
                    case `defer`: alignDelta -= 2; impactDelta -= 4; coachKey = `coach_r1_defer`; break;
                }

                // Name the largest source of misalignment.
                switch (d.misalign) {
                    case `legacy`: impactDelta += 8; alignDelta += 1; if (d.diag === `rigorous`) coachKey = `coach_r1_sharp`; break;
                    case `cost`: impactDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r1_cost` : coachKey; break;
                    case `reach`: impactDelta -= 2; break;
                    case `none`: alignDelta -= 4; impactDelta -= 8; coachKey = `coach_r1_none`; break;
                }

                // Analytical rigor behind the heat map.
                if (d.rigor >= 60) { impactDelta += 6; }
                else if (d.rigor <= 25) { impactDelta -= 5; alignDelta -= 2; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.diag === `rigorous` && d.misalign === `legacy`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Reallocate within the freeze + delivery mix (Errors 2 & 3: reach-over-fit, ask for more).
                const realloc = d.reallocate;          // €M moved from legacy to 2030 capabilities
                const digitalShare = d.mix / 100;      // share delivered digital/blended
                const classroomShare = 1 - digitalShare;

                // Reallocation drives the alignment score up — each €M of the €9.6M is ~5 pts.
                // Reallocating the full €9.6M lifts alignment from 34% toward the low 80s; the
                // remaining headroom comes from doing R3/R4 well (you can't max alignment by money alone).
                alignDelta += realloc * 5.0;

                // Reach: the reallocated euros buy priority-capability learners. Only a fraction of
                // the rebuilt spend lands in the 2030 priority programs (the rest sustains foundational
                // content), so reach scales toward the ~2.800 target rather than ballooning.
                const blendedCost = this.COST_DIGITAL * digitalShare + this.COST_CLASSROOM * classroomShare;
                const PRIORITY_PENETRATION = 0.45;
                const newLearners = Math.round((realloc * 1000000 * PRIORITY_PENETRATION) / blendedCost);
                reachDelta += newLearners;

                // Blended cost per learner moves toward the rebuilt mix (gentle pull, not full replacement).
                costDelta += Math.round((blendedCost - ds.cost) * 0.45);

                // Mode-to-objective fit: protecting relational skills costs reach but preserves the learning objective.
                switch (d.protect) {
                    case `protect`:
                        impactDelta += 10; alignDelta += 2;
                        coachKey = (digitalShare >= 0.85) ? `coach_r2_protectbut` : `coach_r2_protect`;
                        break;
                    case `some`:
                        impactDelta += 3;
                        break;
                    case `none`:
                        // Reach-over-fit: cheap digital on relational skills guts the objective.
                        ds.relationalGutted = true;
                        impactDelta -= 12; alignDelta -= 3;
                        reachDelta += Math.round(newLearners * 0.25); // a little extra raw reach...
                        coachKey = `coach_r2_reachoverfit`;           // ...that changes nothing
                        break;
                }

                if (digitalShare >= 0.9 && d.protect !== `protect`) {
                    coachKey = `coach_r2_alldigital`;
                }
                if (realloc <= 1) {
                    coachKey = `coach_r2_underfunded`;
                }

                summaryKey = (realloc >= 6 && d.protect === `protect` && digitalShare >= 0.5 && digitalShare <= 0.85)
                    ? `sum_r2_good`
                    : (d.protect === `none` ? `sum_r2_gutted` : `sum_r2_weak`);
            } else if (round === 3) {
                // Design the impact measurement system (Error 4: activity as proof).
                switch (d.metric) {
                    case `business`: impactDelta += 22; alignDelta += 2; coachKey = `coach_r3_business`; break;
                    case `learning`: impactDelta += 6; coachKey = `coach_r3_learning`; break;
                    case `activity`: ds.activityOnly = true; impactDelta -= 14; coachKey = `coach_r3_activity`; break;
                }

                // Causal chain rigor links learning to the business-impact index.
                switch (d.chain) {
                    case `explicit`: impactDelta += 12; if (d.metric === `business`) coachKey = `coach_r3_defensible`; break;
                    case `vague`: impactDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_vague` : coachKey; break;
                    case `none`: impactDelta -= 8; coachKey = `coach_r3_nochain`; break;
                }

                // Measurement infrastructure spend (drawn from the reallocated budget; raises cost/learner a touch).
                costDelta += Math.round(d.invest * 12);   // small upward pressure on cost/learner
                if (d.invest >= 0.6) { impactDelta += 8; }
                else if (d.invest <= 0.2) { impactDelta -= 6; if (coachKey === `coach_default` || coachKey === `coach_r3_learning`) coachKey = `coach_r3_underinvest`; }

                summaryKey = (d.metric === `business` && d.chain === `explicit` && d.invest >= 0.4)
                    ? `sum_r3_good`
                    : (d.metric === `activity` ? `sum_r3_activity` : `sum_r3_weak`);
            } else if (round === 4) {
                // Pitch & govern (Errors 3 & 5: ask for more, one-off redesign).
                switch (d.pitch) {
                    case `tradeoff`: alignDelta += 4; impactDelta += 8; coachKey = `coach_r4_tradeoff`; break;
                    case `vision`: impactDelta -= 6; coachKey = `coach_r4_vision`; break;
                    case `moremoney`:
                        ds.askedForMore = true;
                        alignDelta -= 8; impactDelta -= 8; coachKey = `coach_r4_money`;
                        break;
                }

                // Governance cadence — without it, alignment decays back toward 34% by inertia.
                switch (d.governance) {
                    case `quarterly`: alignDelta += 6; impactDelta += 6; coachKey = (coachKey === `coach_r4_tradeoff`) ? `coach_r4_governed` : coachKey; break;
                    case `annual`: alignDelta -= 2; break;
                    case `oneoff`:
                        ds.noGovernance = true;
                        // Decay: a chunk of the alignment gained this game erodes back to baseline.
                        alignDelta -= Math.max(4, Math.round((ds.align - this.ALIGN_BASE) * 0.30));
                        impactDelta -= 4; coachKey = `coach_r4_oneoff`;
                        break;
                }

                // Live stress-test of one assumption.
                switch (d.concede) {
                    case `evidence`: impactDelta += 8; alignDelta += 2; break;
                    case `defend`: impactDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_defend` : coachKey; break;
                    case `popularity`: impactDelta -= 8; alignDelta -= 3; coachKey = `coach_r4_popularity`; break;
                }

                if (d.conviction >= 60) { impactDelta += 4; alignDelta += 2; }
                else if (d.conviction <= 25) { impactDelta -= 4; alignDelta -= 2; }

                summaryKey = (d.pitch === `tradeoff` && d.governance === `quarterly` && d.concede === `evidence`)
                    ? `sum_r4_good`
                    : (ds.askedForMore ? `sum_r4_money` : (ds.noGovernance ? `sum_r4_oneoff` : `sum_r4_weak`));
            }

            // Apply deltas with clamps.
            ds.align = Math.max(0, Math.min(100, Math.round((ds.align + alignDelta) * 10) / 10));
            ds.reach = Math.max(0, Math.round(ds.reach + reachDelta));
            ds.cost = Math.max(this.COST_DIGITAL, Math.round(ds.cost + costDelta));
            ds.impact = Math.max(0, Math.min(100, Math.round(ds.impact + impactDelta)));

            // Budget gauge: the redesign always lives inside the freeze unless the team asked for more.
            ds.budgetUsed = ds.askedForMore ? 18 : this.BUDGET;

            ds.alignHistory.push(ds.align);
            ds.reachHistory.push(ds.reach);
            ds.costHistory.push(ds.cost);
            ds.impactHistory.push(ds.impact);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            return {
                period: state.currentPeriod,
                align: ds.align,
                alignDelta: Math.round(alignDelta * 10) / 10,
                reach: ds.reach,
                reachDelta: Math.round(reachDelta),
                cost: ds.cost,
                costDelta: Math.round(costDelta),
                impact: ds.impact,
                impactDelta: Math.round(impactDelta),
                budgetUsed: ds.budgetUsed,
                askedForMore: ds.askedForMore,
                relationalGutted: ds.relationalGutted,
                activityOnly: ds.activityOnly,
                noGovernance: ds.noGovernance,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

