        // EUR formatting — Dutch/German notation (dot thousands, comma decimal). One symbol only: €.
        _fmtEuro(v) {
            const rounded = Math.round(v);
            const s = String(Math.abs(rounded)).replace(/\B(?=(\d{3})+(?!\d))/g, `.`);
            return `€` + (rounded < 0 ? `-` : ``) + s;
        }

        // €M with one decimal in nl-NL style: "14,6 M€".
        _fmtMillions(v) {
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v).toFixed(1).replace(`.`, `,`);
            return `${sign}${abs} M€`;
        }

        // Reach learners: thousands separator, locale dot.
        _fmtReach(v) {
            return String(Math.round(v)).replace(/\B(?=(\d{3})+(?!\d))/g, `.`);
        }

