        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.alignHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                eldChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.alignHistory },
                        { data: ds.impactHistory },
                        { data: ds.reachHistory }
                    ]
                }
            };
        }

        // _composite(ds): single source of truth for the 0-100 score (v1.0.0 formula, verbatim).
        _composite(ds) {
            const align = Math.round(ds.align);
            const reach = Math.round(ds.reach);
            const cost = Math.round(ds.cost);
            const impact = Math.round(ds.impact);
            const reachScore = Math.max(0, Math.min(100, (reach / this.REACH_TARGET) * 100));
            const costScore = Math.max(0, Math.min(100,
                ((this.COST_CLASSROOM - cost) / (this.COST_CLASSROOM - this.COST_DIGITAL)) * 100));
            return Math.round(align * 0.34 + impact * 0.30 + reachScore * 0.22 + costScore * 0.14);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const align = Math.round(ds.align);
            const reach = Math.round(ds.reach);
            const cost = Math.round(ds.cost);
            const impact = Math.round(ds.impact);

            // Composite via _composite(ds) — single source of truth (v1.0.0 formula).
            const composite = this._composite(ds);

            const aligned = align >= 70;
            const reaching = reach >= 1500;
            const measured = impact >= 65;
            const failed = ds.askedForMore || ds.relationalGutted || ds.activityOnly || ds.noGovernance;

            // A committed classic error caps the outcome — the Board never renews on a broken case,
            // however strong the surrounding numbers look. Error branches are checked FIRST.
            let performanceKey = `grade_folded`;
            if (ds.askedForMore) performanceKey = `grade_askedmore`;
            else if (ds.relationalGutted) performanceKey = `grade_relational`;
            else if (ds.activityOnly) performanceKey = `grade_activity`;
            else if (ds.noGovernance) performanceKey = `grade_decays`;
            else if (aligned && reaching && measured && composite >= 78) performanceKey = `grade_engine`;
            else if (aligned && measured) performanceKey = `grade_renewed`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (aligned && reaching && measured && !failed) insights.push(window.mySimulation.t(`insight_engine`));
            else if (failed) insights.push(window.mySimulation.t(`insight_failed`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.askedForMore) insights.push(window.mySimulation.t(`insight_money`));
            if (ds.relationalGutted) insights.push(window.mySimulation.t(`insight_relational`));
            if (ds.activityOnly) insights.push(window.mySimulation.t(`insight_activity`));
            if (ds.noGovernance) insights.push(window.mySimulation.t(`insight_governance`));
            if (cost <= 500) insights.push(window.mySimulation.t(`insight_cost`));
            if (aligned && measured && !failed) insights.push(window.mySimulation.t(`insight_proven`));

            return {
                align: align,
                reach: reach,
                cost: cost,
                impact: impact,
                aligned: aligned,
                reaching: reaching,
                measured: measured,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: (aligned && reaching && measured && !failed),
                failed: failed,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = (k) => window.mySimulation.t(k);
            const esc = (x) => String(x == null ? `` : x).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || t(s.performanceKey || `grade_folded`);
            const badge = (ok, okKey, noKey) => `<span class="eldsim-cm-badge ${ok ? `eldsim-cm-ok` : `eldsim-cm-no`}">${esc(t(ok ? okKey : noKey))}</span>`;
            const kpi = (label, val) => `<div class="eldsim-cm-kpi"><div class="eldsim-cm-kpi-v">${esc(val)}</div><div class="eldsim-cm-kpi-l">${esc(label)}</div></div>`;
            const insights = (s.insights || []).map((i) => `<li>${esc(i)}</li>`).join(``);
            let badges = badge(s.aligned === true, `cm_badge_aligned`, `cm_badge_misaligned`)
                       + badge(s.reaching === true, `cm_badge_reaching`, `cm_badge_reachshort`)
                       + badge(s.measured === true, `cm_badge_measured`, `cm_badge_activity`);
            if (s.failed) badges += `<span class="eldsim-cm-badge eldsim-cm-no">${esc(t(`cm_badge_classicerror`))}</span>`;
            const reach = (s.reach != null) ? this._fmtReach(Number(s.reach)) : `\u2014`;
            const cost = (s.cost != null) ? this._fmtEuro(Number(s.cost)) : `\u2014`;
            return `<div class="eldsim-cm">`
                + `<div class="eldsim-cm-head"><div class="eldsim-cm-score">${score}<span class="eldsim-cm-max">/100</span></div>`
                + `<div class="eldsim-cm-grade">${esc(grade)}</div></div>`
                + `<div class="eldsim-cm-badges">${badges}</div>`
                + `<div class="eldsim-cm-kpis">`
                + kpi(t(`cm_kpi_align`), (s.align != null ? s.align : `\u2014`))
                + kpi(t(`cm_kpi_reach`), reach)
                + kpi(t(`cm_kpi_cost`), cost)
                + kpi(t(`cm_kpi_impact`), (s.impact != null ? s.impact : `\u2014`))
                + kpi(t(`cm_kpi_index`), score)
                + `</div>`
                + (insights ? `<ul class="eldsim-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
