            if (ds.askedForMore) return window.mySimulation.t(`hint_money`);
            if (ds.relationalGutted) return window.mySimulation.t(`hint_relational`);
            if (ds.activityOnly) return window.mySimulation.t(`hint_activity`);
            if (state.currentPeriod >= 4 && ds.noGovernance) return window.mySimulation.t(`hint_governance`);
            if (state.currentPeriod >= 2 && ds.align < 50) return window.mySimulation.t(`hint_align`);
            if (state.currentPeriod >= 3 && ds.impact < 40) return window.mySimulation.t(`hint_impact`);
            if (ds.align >= 80 && ds.impact >= 70 && ds.reach >= 1500) return window.mySimulation.t(`hint_strong`);
